import { test } from "@playwright/test";

const EMAIL = process.env.E2E_EMAIL!;
const PASSWORD = process.env.E2E_PASSWORD!;

test("inspect cancel flow", async ({ page }) => {
  await page.goto("/sign-in");
  await page.locator('input[name="email"]').fill(EMAIL);
  await page.locator('input[name="password"]').fill(PASSWORD);
  await page.getByRole("button", { name: /sign in/i }).click();
  await page.waitForURL(/\/account/);

  await page.goto("/account/membership");
  await page.waitForLoadState("networkidle");
  await page.screenshot({ path: "artifacts/probe-before-cancel.png", fullPage: true });

  await page.getByRole("button", { name: /cancel membership/i }).first().click();
  await page.waitForTimeout(1500);
  await page.screenshot({ path: "artifacts/probe-after-cancel-click.png", fullPage: true });

  const buttons = await page.getByRole("button").all();
  for (const b of buttons) console.log("BUTTON:", JSON.stringify(await b.textContent()));

  const dialogCount = await page.getByRole("dialog").count();
  const alertdialogCount = await page.getByRole("alertdialog").count();
  console.log("dialogs:", dialogCount, "alertdialogs:", alertdialogCount);
});
